const mongoose = require('mongoose');
const { toJSON, paginate } = require('./plugins');

/**
 * DATA is generated by cronjob
 */
const scheme = mongoose.Schema({
    //kol fields
    kol        : { type : mongoose.Schema.Types.ObjectId, ref : 'User', required : true },
    kolCode    : { type : mongoose.Schema.Types.ObjectId, ref : 'Voucher', required : true },
    settlement : { type : mongoose.Schema.Types.ObjectId, ref : 'Image', default : null },
    ordersRef  : [{ type : mongoose.Schema.Types.ObjectId, ref : 'Order', required : true }],
    bonus      : { type : Number, required : true },
    totalOrders : { type : Number, default : 0 },
    // regular report fields
    reportType       : { type : String, require : true, enum : ['monthly'] },
    date             : { type : String, require : true }, //2000-12-31 // 2000-12
    year             : { type : Number, require : true }, //2000
    month            : { type : Number, require : true }, //0-12
    day              : { type : Number, require : true }, //1-31 for type = daily // 1 for type = monthly
    catSummary       : [{ category : { type : mongoose.Schema.Types.ObjectId, ref : 'Category' }, quantity : { type : Number } }],
    quantity         : { type : Number, required : true },
    orders           : { type : Number, required : true },
    incompleteOrders : { type : Number, require : true },
    cancelledOrders  : { type : Number, require : true },
    memberOrders     : { type : Number, require : true },
    nonMemberOrders  : { type : Number, require : true },
    turnover         : { type : Number, required : true },
    marketing        : { type : Number, default : null },
  }, {
    timestamps : true,
  }
);

// add plugin that converts mongoose to json
scheme.plugin(toJSON);
scheme.plugin(paginate);

/**
 * @typedef KolSales
 */
const KolSales = mongoose.model('KolSales', scheme);

module.exports = KolSales;
